import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFlow Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFlow/aireflow-v2-42-0.md","filePath":"aireblock-releases/AireFlow/aireflow-v2-42-0.md","lastUpdated":1791818592000}`),a={name:`aireblock-releases/AireFlow/aireflow-v2-42-0.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireflow-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireflow-icon.png"> AireFlow Release Notes</span> <a class="header-anchor" href="#aireflow-release-notes" aria-label="Permalink to “AireFlow Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 2.42.0<br><strong>Release Date:</strong> 21 October 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Automatic Escaping of Mapped Values (FLOW-625, FLOW-1369)</li><li>New Agentic Task Type (FLOW-1263, FLOW-1343, FLOW-1370)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>HTTP Tasks No Longer Fail When a Header Name Is Blank (FLOW-1365)</li></ul><h3 id="⚠️-upgrade-notes" tabindex="-1">⚠️ Upgrade Notes <a class="header-anchor" href="#⚠️-upgrade-notes" aria-label="Permalink to “⚠️ Upgrade Notes”">​</a></h3><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p><strong>Automatic escaping is on for new tasks and off for existing tasks.</strong> Tasks created after this release escape mapped values automatically. Existing tasks, including workflow definitions stored in Git, keep their current behaviour until you opt them in. Once a task is opted in through the designer, it can&#39;t be switched back.</p><p>Before opting in an existing task, review its mappings for manual escaping workarounds, such as <code>replace</code> filters that escape quotes, backslashes or new lines. AireFlow no longer detects and removes these automatically, so leaving them in place may escape values twice.</p></div><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="automatic-escaping-of-mapped-values-flow-625" tabindex="-1">Automatic Escaping of Mapped Values (FLOW-625) <a class="header-anchor" href="#automatic-escaping-of-mapped-values-flow-625" aria-label="Permalink to “Automatic Escaping of Mapped Values (FLOW-625)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>AireFlow now <a href="https://docs.flow.aireinnovate.com/docs/workflows/escaping.html" target="_blank" rel="noreferrer">automatically escapes mapped values</a> to suit where they&#39;re going, such as JSON, XML, mutations and URLs. Line breaks, quotes, backslashes and other special characters from form data no longer break HTTP request bodies or mutations. This replaces the manual liquid workarounds that were previously needed. Automatic escaping is set per task definition. New tasks have it switched on by default. Existing tasks keep their previous behaviour and show an option to opt in, which is one-way. Workflow definitions already stored in Git behave as before until they&#39;re updated to opt in.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can map form answers straight into your HTTP tasks and mutations without worrying about what people type. A comment with line breaks, quotation marks or a backslash will no longer cause a task to fail, and you no longer need complicated workarounds in your mappings.</p></div><h4 id="new-agentic-task-type-flow-1263" tabindex="-1">New Agentic Task Type (FLOW-1263) <a class="header-anchor" href="#new-agentic-task-type-flow-1263" aria-label="Permalink to “New Agentic Task Type (FLOW-1263)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>A new <a href="https://docs.flow.aireinnovate.com/docs/tasks/agentic.html" target="_blank" rel="noreferrer">Agentic task type</a> lets a workflow hand work to an AI agent. You choose the agent and write a prompt, which can include mapped values from the workflow. The agent&#39;s response is saved to the task&#39;s state, and the task completes automatically. The task type is available to tenants where it has been enabled.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now add AI-powered steps to your workflows, for example to summarise, classify or extract information from submitted data. The results are passed on to later steps automatically, without anyone having to act on the task.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="http-tasks-no-longer-fail-when-a-header-name-is-blank-flow-1365" tabindex="-1">HTTP Tasks No Longer Fail When a Header Name Is Blank (FLOW-1365) <a class="header-anchor" href="#http-tasks-no-longer-fail-when-a-header-name-is-blank-flow-1365" aria-label="Permalink to “HTTP Tasks No Longer Fail When a Header Name Is Blank (FLOW-1365)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>HTTP tasks with a header whose name had been left blank failed at runtime with an error and were retried. These tasks now run correctly.</p></div>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};